let _markdown = "\n\nWhat it does? [#what-it-does]\n\n<FeedbackBlock id=\"a2b6239d9a5eee20\" body=\"loader() provides an interface for Fumadocs to integrate with different content sources.\">\n  `loader()` provides an interface for Fumadocs to integrate with different content sources.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"6aecd4b99370c07d\" body=\"Generate page slugs and page tree.Assign URL to each page.Output useful utilities to interact with content.\">\n  * Generate [page slugs and page tree](/docs/headless/page-conventions).\n  * Assign URL to each page.\n  * Output useful utilities to interact with content.\n</FeedbackBlock>\n\n<Callout type=\"warn\" title=\"Important to Know\">\n  * `loader()` is a server-side API, not a build-time magic or browser compatible API.\n  * It uses in-memory storage, the files are passed from your content sources.\n</Callout>\n\nUsage [#usage]\n\n<FeedbackBlock id=\"b6ef9e1db0965a58\" body=\"You can use it with content sources like Fumadocs MDX, see source for details.\">\n  You can use it with content sources like Fumadocs MDX, see [`source`](/docs/headless/source-api/source) for details.\n</FeedbackBlock>\n\n```ts\nimport { loader } from 'fumadocs-core/source';\nimport { docs } from 'fumadocs-mdx:collections/server';\n\nexport const source = loader({\n  source: docs.toFumadocsSource(),\n  baseUrl: '/docs',\n});\n```\n\nURL [#url]\n\n<FeedbackBlock id=\"a18f4b3082485b05\" body=\"You can override the base URL, or specify a function to generate URL for each page.\">\n  You can override the base URL, or specify a function to generate URL for each page.\n</FeedbackBlock>\n\n```ts\nimport { loader } from 'fumadocs-core/source';\n\nloader({\n  baseUrl: '/docs',\n  // or you can customise it with function\n  url(slugs, locale) {\n    if (locale) return '/' + [locale, 'docs', ...slugs].join('/');\n    return '/' + ['docs', ...slugs].join('/');\n  },\n});\n```\n\nSlugs [#slugs]\n\n<FeedbackBlock id=\"cd19c97789edf7d8\" body=\"Define a custom function to generate slugs from page files.\">\n  Define a custom function to generate slugs from page files.\n</FeedbackBlock>\n\n```ts\nimport { loader } from 'fumadocs-core/source';\n\nloader({\n  slugs(file) {\n    console.log(file.path, file.data);\n    // or return `undefined` to fallback to default value\n    return ['my', 'slug'];\n  },\n});\n```\n\nIcons [#icons]\n\n<FeedbackBlock id=\"c3019b86ddbac68c\" body=\"Load the icon property specified by page and meta files.\">\n  Load the [icon](/docs/headless/page-conventions#icons) property specified by page and meta files.\n</FeedbackBlock>\n\n```ts\nimport { loader } from 'fumadocs-core/source';\nimport { icons } from 'lucide-react';\nimport { createElement } from 'react';\n\nloader({\n  icon(icon) {\n    if (!icon) {\n      // You may set a default icon\n      return;\n    }\n\n    if (icon in icons) return createElement(icons[icon as keyof typeof icons]);\n  },\n});\n```\n\nI18n [#i18n]\n\n<FeedbackBlock id=\"a6b9b2f2ddb43b39\" body=\"Pass the i18n config to loader.\">\n  Pass the `i18n` config to loader.\n</FeedbackBlock>\n\n```ts title=\"lib/source.ts\"\nimport { i18n } from '@/lib/i18n';\nimport { loader } from 'fumadocs-core/source';\n\nexport const source = loader({\n  i18n, // [!code highlight]\n});\n```\n\n<FeedbackBlock id=\"7dee3f8d8abf3ced\" body=\"With i18n enabled, loader will generate a page tree for every locale.\">\n  With i18n enabled, loader will generate a page tree for every locale.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"3a64f041644e172e\" body=\"If translations are missing for a page, it fallbacks to fallbackLanguage.\">\n  If translations are missing for a page, it fallbacks to [`fallbackLanguage`](/docs/headless/internationalization#fallback-language).\n</FeedbackBlock>\n\nOutput [#output]\n\n<FeedbackBlock id=\"bc4cc9798af405d8\" body=\"The loader outputs a source object.\">\n  The loader outputs a source object.\n</FeedbackBlock>\n\nGet Page [#get-page]\n\n<FeedbackBlock id=\"4091bb9aa63be3fa\" body=\"Get page with slugs.\">\n  Get page with slugs.\n</FeedbackBlock>\n\n```ts\nimport { source } from '@/lib/source';\n\nsource.getPage(['slug', 'of', 'page']);\n\n// with i18n\nsource.getPage(['slug', 'of', 'page'], 'locale');\n```\n\nGet Pages [#get-pages]\n\n<FeedbackBlock id=\"11d97b01521a1dd8\" body=\"Get a list of page available for locale.\">\n  Get a list of page available for locale.\n</FeedbackBlock>\n\n```ts\nimport { source } from '@/lib/source';\n\n// from any locale\nsource.getPages();\n\n// for a specific locale\nsource.getPages('locale');\n```\n\nPage Tree [#page-tree]\n\n```ts\nimport { source } from '@/lib/source';\n\n// without i18n\nsource.getPageTree();\n\n// with i18n\nsource.getPageTree('locale');\n```\n\nGet from Node [#get-from-node]\n\n<FeedbackBlock\n  id=\"cc2db66512c8a59b\"\n  body=\"The page tree nodes contain references to their original file path.\nYou can find their original page or meta file from the tree nodes.\"\n>\n  The page tree nodes contain references to their original file path.\n  You can find their original page or meta file from the tree nodes.\n</FeedbackBlock>\n\n```ts\nimport { source } from '@/lib/source';\n\nsource.getNodePage(pageNode);\nsource.getNodeMeta(folderNode);\n```\n\nParams [#params]\n\n<FeedbackBlock\n  id=\"d87310031b548086\"\n  body=\"A function to generate output for Next.js generateStaticParams.\nThe generated parameter names will be slug: string[] and lang: string (i18n only).\"\n>\n  A function to generate output for Next.js `generateStaticParams`.\n  The generated parameter names will be `slug: string[]` and `lang: string` (i18n only).\n</FeedbackBlock>\n\n```ts title=\"app/[[...slug]]/page.tsx\"\nimport { source } from '@/lib/source';\n\nexport function generateStaticParams() {\n  return source.generateParams();\n}\n```\n\nLanguage Entries [#language-entries]\n\n<FeedbackBlock id=\"e25cca6740912688\" body=\"Get available languages and its pages.\">\n  Get available languages and its pages.\n</FeedbackBlock>\n\n```ts\nimport { source } from '@/lib/source';\n\n// language -> pages\nconst entries = source.getLanguages();\n```\n\nClient API [#client-api]\n\n<FeedbackBlock id=\"4cfa7ca46a813a42\" body=\"Loader API is best when used in RSC environments, which allows passing JSX nodes across the server-client boundary.\">\n  Loader API is best when used in RSC environments, which allows passing JSX nodes across the server-client boundary.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"aa0a707903f0f48e\" body=\"For non-RSC environments, it provides a tiny serialization layer.\">\n  For non-RSC environments, it provides a tiny serialization layer.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Server\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Server\">\n      Server\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Client\">\n      Client\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Server\">\n    ```ts\n    import { source } from '@/lib/source';\n\n    // where you pass loader data\n    async function loader() {\n      const pageTree = source.getPageTree();\n\n      return {\n        pageTree: await source.serializePageTree(pageTree),\n      };\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Client\">\n    ```tsx\n    import { useFumadocsLoader } from 'fumadocs-core/source/client';\n\n    function MyComponent() {\n      // `useLoaderData()` receives loader data (provided by your React framework)\n      const { pageTree, ...data } = useFumadocsLoader(useLoaderData());\n\n      // now render it (e.g. via Fumadocs UI)\n      return <DocsLayout tree={pageTree}>...</DocsLayout>;\n    }\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n";
